CREATE DATABASE IF NOT EXISTS online_grievance_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE online_grievance_system;
CREATE TABLE roles (id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(32) NOT NULL UNIQUE);
INSERT INTO roles (name) VALUES ('citizen'),('department_admin'),('super_admin');
CREATE TABLE departments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id TINYINT UNSIGNED NOT NULL, department_id INT UNSIGNED NULL, full_name VARCHAR(140) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(30) NULL, address VARCHAR(255) NULL, password_hash VARCHAR(255) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(department_id) REFERENCES departments(id), INDEX idx_users_department(department_id));
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, department_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, description TEXT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_category_department(name,department_id), FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE grievances (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tracking_number VARCHAR(32) NOT NULL UNIQUE, citizen_id BIGINT UNSIGNED NOT NULL, department_id INT UNSIGNED NOT NULL, category_id INT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, location VARCHAR(255) NOT NULL, status ENUM('Submitted','Under Review','Assigned','In Progress','Resolved','Closed','Rejected','Reopened') NOT NULL DEFAULT 'Submitted', expected_resolution_date DATE NULL, resolution_details TEXT NULL, rejection_reason TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(citizen_id) REFERENCES users(id), FOREIGN KEY(department_id) REFERENCES departments(id), FOREIGN KEY(category_id) REFERENCES categories(id), INDEX idx_grievance_dept_status(department_id,status), INDEX idx_grievance_due(status,expected_resolution_date), INDEX idx_grievance_citizen(citizen_id,created_at));
CREATE TABLE grievance_attachments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, grievance_id BIGINT UNSIGNED NOT NULL, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(100) NOT NULL UNIQUE, mime_type VARCHAR(100) NOT NULL, file_size INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(grievance_id) REFERENCES grievances(id) ON DELETE CASCADE);
CREATE TABLE grievance_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, grievance_id BIGINT UNSIGNED NOT NULL, previous_status VARCHAR(30) NULL, new_status VARCHAR(30) NOT NULL, updated_by BIGINT UNSIGNED NOT NULL, remarks TEXT NULL, is_public TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(grievance_id) REFERENCES grievances(id) ON DELETE CASCADE, FOREIGN KEY(updated_by) REFERENCES users(id), INDEX idx_history_grievance(grievance_id,created_at));
CREATE TABLE officer_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, grievance_id BIGINT UNSIGNED NOT NULL, officer_id BIGINT UNSIGNED NOT NULL, assigned_by BIGINT UNSIGNED NOT NULL, assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(grievance_id) REFERENCES grievances(id) ON DELETE CASCADE, FOREIGN KEY(officer_id) REFERENCES users(id), FOREIGN KEY(assigned_by) REFERENCES users(id), INDEX idx_assignment_active(grievance_id,active));
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, grievance_id BIGINT UNSIGNED NULL, message VARCHAR(500) NOT NULL, read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(grievance_id) REFERENCES grievances(id) ON DELETE SET NULL, INDEX idx_notification_user(user_id,read_at));
CREATE TABLE feedback (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, grievance_id BIGINT UNSIGNED NOT NULL UNIQUE, citizen_id BIGINT UNSIGNED NOT NULL, rating TINYINT UNSIGNED NOT NULL, comments TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(grievance_id) REFERENCES grievances(id) ON DELETE CASCADE, FOREIGN KEY(citizen_id) REFERENCES users(id), CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, details TEXT NULL, ip_address VARCHAR(45) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_audit_created(created_at));
